index 53295b9..68759a8 100644
--- a/sistema/sistema.cpp
+++ b/sistema/sistema.cpp
@@ -2044,9 +2044,42 @@ bool handle_watch_pf(vaddr cr2)
  */
 bool handle_watch_ss()
 {
-/// @todo Gestire l'evento
-// ( SOLUZIONE 2024-06-07
-//   SOLUZIONE 2024-06-07 )
+    watch_des *w = &watch_state;
+
+    if (!w->v || !esecuzione->being_watched)
+        return false;
+
+    vaddr addr = w->v;
+    natq size = w->size;
+    natq new_value;
+
+    switch(size) {
+    case 1: { natb v; memcpy(&v, voidptr_cast(addr), 1); new_value = v; break; }
+    case 2: { natw v; memcpy(&v, voidptr_cast(addr), 2); new_value = v; break; }
+    case 4: { natl v; memcpy(&v, voidptr_cast(addr), 4); new_value = v; break; }
+    case 8: { memcpy(&new_value, voidptr_cast(addr), 8); break; }
+    default: return false;
+    }
+
+    esecuzione->being_watched = false;
+
+    if (new_value != w->old_value) {
+        w->old_value = new_value;
+        esecuzione->new_watch_value = new_value;
+
+        if (w->watcher_waiting) {
+            w->watcher_waiting->new_watch_value = new_value;
+            inserimento_lista(pronti, w->watcher_waiting);
+            w->watcher_waiting = nullptr;
+        }
+    }
+
+    tab_iter it(esecuzione->cr3, addr, size);
+    while (it.down())
+        ;
+    it.get_e() &= ~BIT_RW;
+
+    return true;
 }

